function portrait(o){const b=pbuf(16,16,'1');
  prect(b,2,13,12,3,o.coat);prect(b,3,12,10,1,o.coat);
  ppoly(b,[[4,4],[12,4],[12,11],[10,13],[6,13],[4,11]],'m');
  pset(b,4,11,'n');pset(b,11,11,'n');prect(b,6,12,4,1,'n');
  pset(b,6,7,'0');pset(b,9,7,'0');prect(b,7,10,2,1,o.mouth||'n');pset(b,7,9,'n');pset(b,8,9,'n');
  (o.draw||(()=>{}))(b);return b}
