/* lighthouse on the home screen (48x80) */
function towerBuf(st){const b=pbuf(48,80);const lk=st.looked,lit=st.won,F=st.floors;
  if(!lk){prect(b,0,0,48,80,'0');pset(b,24,70,'f');pset(b,24,69,'g');pset(b,23,70,'c');pset(b,25,70,'c');return b}
  if(!st.bare){psky(b,62,!lit);psea(b,62,12)}ppoly(b,[[4,80],[8,68],[18,64],[32,64],[42,68],[46,80]],'8');pnoise(b,4,64,42,16,'9',0.25,3);
  const T=(y)=>{const w=Math.round(10+(y-16)*0.18);return[24-w/2|0,w]};
  for(let y=16;y<66;y++){const[x,w]=T(y);prect(b,x,y,w,1,'9');pset(b,x,y,'a');pset(b,x+1,y,'a');pset(b,x+w-1,y,'8')}
  const floor=(y0,y1,on)=>{for(let y=y0;y<y1;y++){const[x,w]=T(y);if(!on)pnoise(b,x,y,w,1,'8',0.35,y*7)}
    const[x,w]=T((y0+y1)>>1);prect(b,x+w/2-1|0,y0+2,3,4,on?'g':'0');if(on)pset(b,(x+w/2)|0,y0+3,'h');for(let y=y0;y<y1;y+=1){}const[x2,w2]=T(y1);prect(b,x2,y1,w2,1,'8')};
  floor(54,64,!!st.hearth);floor(44,54,!!F.work);floor(34,44,!!F.study);floor(24,34,!!F.gallery);
  for(let y=62;y<66;y++){const[x,w]=T(y);}prect(b,22,58,4,7,'0');if(st.hearth){prect(b,23,61,2,4,'f');pset(b,23,62,'g');pset(b,24,63,'h')}else pset(b,24,63,'f');
  /* gallery + lantern */
  prect(b,14,22,20,2,F.gallery?'p':'9');for(let x=15;x<33;x+=2)pset(b,x,21,F.gallery?'q':'9');
  prect(b,18,12,12,10,F.lantern?'1':'8');for(let x=19;x<29;x+=3)prect(b,x,13,2,8,lit?'g':(F.lantern?'3':'9'));if(lit){prect(b,21,15,6,4,'h')}
  ppoly(b,[[16,12],[24,5],[32,12]],F.lantern?'i':'9');pset(b,24,4,'p');
  if(lit&&!st.bare){for(let i=0;i<24;i++){pset(b,15-i,12-i*0.35,'g');pset(b,15-i,13-i*0.35,'h');pset(b,33+i,12-i*0.35,'g');pset(b,33+i,13-i*0.35,'h')}}
  return b}
